#!/usr/bin/env python3
"""Test real local candidate tarballs; never publish or execute consumer install scripts."""
from pathlib import Path
import json,subprocess,tempfile,tarfile
ROOT=Path(__file__).resolve().parents[1]
def run(args,**kw):return subprocess.run(args,check=True,text=True,**kw)
with tempfile.TemporaryDirectory(prefix='director-studio-') as temp:
    temp=Path(temp);archives=[]
    for name in ['core','studio']:
        result=run(['npm','pack','--json','--pack-destination',str(temp)],cwd=ROOT/'packages'/name,capture_output=True)
        archive=temp/json.loads(result.stdout)[0]['filename'];archives.append(str(archive))
        with tarfile.open(archive,'r:gz') as tar:
            for member in tar.getmembers():
                relative=member.name.removeprefix('package/')
                assert member.isfile() and member.name.startswith('package/') and '..' not in Path(relative).parts
                assert relative in ['package.json','README.md','LICENSE','prepare.mjs'] or (relative.startswith('src/') and relative.endswith(('.js','.d.ts')))
            manifest=json.load(tar.extractfile('package/package.json'));assert manifest['private'] is True
            assert tar.extractfile('package/LICENSE').read()==(ROOT/'LICENSE').read_bytes()
    consumer=temp/'consumer';consumer.mkdir();(consumer/'package.json').write_text('{"private":true,"type":"module"}')
    run(['npm','install','--ignore-scripts','--no-audit','--no-fund',*archives,'typescript@5.8.3'],cwd=consumer)
    (consumer/'smoke.mjs').write_text("import {createSample,validateProject,exportSubtitles} from '@dom-director/studio'; import {cloneData} from '@dom-director/core/data'; import {setAppearance,distributeCaptionWords} from '@dom-director/studio/editing'; import {saveProjectBundle,readProjectBundle} from '@dom-director/studio/media'; const p=createSample();if(!validateProject(cloneData(p)).ok||!exportSubtitles(p).text.startsWith('WEBVTT'))throw Error('Invalid installed consumer');const bundle=await saveProjectBundle(p,{bytes(){throw Error('Unexpected audio access')}});if((await readProjectBundle(bundle)).project.id!==p.id)throw Error('Media subpath failed');if(setAppearance(p,'cc.overview.0',{size:42}).tracks[3].clips[0].style.size!==42)throw Error('Editing subpath failed');if(!distributeCaptionWords(p,'cc.overview.0').tracks[3].clips[0].words.length)throw Error('Word timing subpath failed');console.log('Installed Studio, editing and media consumers passed');")
    run(['node','smoke.mjs'],cwd=consumer)
    (consumer/'timeline.mjs').write_text("import {createSample} from '@dom-director/studio'; import {createTimelineSnapper,moveTimelineKeyframe} from '@dom-director/studio/editing'; const p=createSample(),r=createTimelineSnapper(p,{clipId:'camera.overview',keyId:'camera.to.overview',operation:'keyframe',pixelsPerSecond:100}).snap(2440);if(r.deltaMs!==2490||r.guide?.timeMs!==3490)throw Error('Installed timeline snapping failed');if(moveTimelineKeyframe(p,'camera.overview','camera.to.overview',3490).tracks[0].clips[0].keys[1].atMs!==3490)throw Error('Installed key retiming failed');console.log('Installed timeline precision consumers passed');")
    run(['node','timeline.mjs'],cwd=consumer)
    (consumer/'audio-export.mjs').write_text("import {createSample} from '@dom-director/studio'; import {planVoiceMix,renderVoiceMix} from '@dom-director/studio/audio-export'; if(typeof document!=='undefined'||typeof renderVoiceMix!=='function'||planVoiceMix(createSample()).clips.length!==3)throw Error('Installed audio-export entry failed');")
    run(['node','audio-export.mjs'],cwd=consumer)
    (consumer/'audio-export.ts').write_text("import {createSample} from '@dom-director/studio'; import {createMediaBank} from '@dom-director/studio/media'; import {planVoiceMix,renderVoiceMix,type VoiceMixPlan} from '@dom-director/studio/audio-export'; const plan:VoiceMixPlan=planVoiceMix(createSample(),{channels:1,sampleRate:48000}); void renderVoiceMix(createSample(),createMediaBank(),{signal:new AbortController().signal,onProgress:p=>{const stage:string=p.stage;void stage;}});\n// @ts-expect-error unsupported sample rate\nplanVoiceMix(createSample(),{sampleRate:8000});\n// @ts-expect-error output is mono or stereo\nplanVoiceMix(createSample(),{channels:6});\n// @ts-expect-error range is expressed in milliseconds\nplanVoiceMix(createSample(),{range:{startMs:'0',endMs:1000}});\n")
    for filename in ['studio-selection.ts','studio-selection.mjs','studio-caption-search.ts','studio-caption-search.mjs']:
        (consumer/filename).write_text((ROOT/'package-tests'/filename).read_text())
    run(['node','studio-selection.mjs'],cwd=consumer)
    run(['node','studio-caption-search.mjs'],cwd=consumer)
    (consumer/'audition.ts').write_text((ROOT/'package-tests/studio-audition.ts').read_text())
    (consumer/'audition.mjs').write_text("import {createTakeAuditioner} from '@dom-director/studio/media'; const a=createTakeAuditioner({bank:{context(){throw Error('Unexpected context access');},async load(){throw Error('Unexpected loading');}}}); if(a.inspect().state!=='idle')throw Error('Audition import failed');a.destroy();if(a.inspect().state!=='destroyed')throw Error('Audition lifecycle failed');")
    run(['node','audition.mjs'],cwd=consumer)
    (consumer/'timeline.ts').write_text((ROOT/'package-tests/studio-timeline.ts').read_text())
    (consumer/'timing-links.ts').write_text((ROOT/'package-tests/studio-timing-links.ts').read_text())
    (consumer/'timing-links.mjs').write_text("import {createSample,findClip,LINKED_STUDIO_VERSION} from '@dom-director/studio'; import {distributeCaptionWords,stampCaptionWord} from '@dom-director/studio/editing'; import {linkKeyframeToCaptionWord,describeTimingLinks} from '@dom-director/studio/timing-links'; import {saveProjectBundle,readProjectBundle} from '@dom-director/studio/media'; let p=distributeCaptionWords(createSample(),'cc.overview.0'); p=linkKeyframeToCaptionWord(p,'camera.overview','camera.to.overview',{captionId:'cc.overview.0',wordIndex:1,offsetMs:200}); const r=describeTimingLinks(p)[0]; if(p.studioVersion!==LINKED_STUDIO_VERSION||typeof document!=='undefined')throw Error('Linked project contract failed'); const q=stampCaptionWord(p,r.captionId,1,'start',findClip(p,r.captionId).clip.words[1].startMs+1); if(describeTimingLinks(q)[0].sourceTimeMs!==r.sourceTimeMs+1)throw Error('Persistent follow failed'); const opened=await readProjectBundle(await saveProjectBundle(q,{bytes(){throw Error('Unexpected media access');}})); if(JSON.stringify(opened.project)!==JSON.stringify(q))throw Error('Linked round-trip failed');")
    run(['node','timing-links.mjs'],cwd=consumer)

    (consumer/'smoke.ts').write_text("import {createSample,editProject,createEvaluator,type Project} from '@dom-director/studio'; import {setAppearance,addKeyframe,distributeCaptionWords} from '@dom-director/studio/editing'; import {createMediaBank,createTransport,generateVoiceTake,type VoiceProvider} from '@dom-director/studio/media'; const p:Project=createSample();const q=editProject(p,d=>{d.title='Typed edit';});createEvaluator(q);const bank=createMediaBank();const transport=createTransport({bank,onFrame:t=>{const n:number=t;void n;}});transport.load(p);const provider:VoiceProvider={capabilities:{name:'Local host',voices:[{id:'a',styles:['calm']}]},generate:async request=>({bytes:new ArrayBuffer(1),mime:'audio/wav'})};void generateVoiceTake(provider,{text:'Text',voiceId:'a',style:'calm',revision:0,clipId:'voice'});\n// @ts-expect-error snapshots are immutable\np.title='unsafe';\n// @ts-expect-error unsupported timeline coordinate type\ncreateEvaluator(p).sample('1',{});\n// @ts-expect-error audio must be bytes, not a URL\nvoid bank.ingest('a','A','audio/wav','https://example.invalid');\n")
    (consumer/'editing.ts').write_text("import {createSample} from '@dom-director/studio'; import {setAppearance,addKeyframe,distributeCaptionWords} from '@dom-director/studio/editing'; const p=createSample(); distributeCaptionWords(p,'cc.overview.0'); setAppearance(p,'cc.overview.0',{size:42},{scope:'track'}); addKeyframe(p,'camera.overview',2000,{zoom:2});\n// @ts-expect-error unknown scope\nsetAppearance(p,'cc.overview.0',{}, {scope:'all-scenes'});\n// @ts-expect-error stable key IDs cannot be supplied\naddKeyframe(p,'camera.overview',2000,{id:'different'});\n")
    run([str(consumer/'node_modules/.bin/tsc'),'--noEmit','--strict','--module','NodeNext','--target','ES2022','smoke.ts','editing.ts','timeline.ts','audio-export.ts','timing-links.ts','audition.ts','studio-selection.ts','studio-caption-search.ts'],cwd=consumer)
